typedef struct { int irq; void (*rx_callback)(void*); void* cb_data; } uart_port_t;

void uart_disable_irq(int irq) { (void)irq; }
void uart_release_observer(uart_port_t* p) { (void)p; }
void uart_destroy_endpoint(uart_port_t* p) { (void)p; }
void uart_free_port(uart_port_t* p) { (void)p; }
void uart_set_baud(uart_port_t* p, int baud) { (void)p; (void)baud; }

void uart_teardown_rx_handler(uart_port_t* port)
{
  uart_release_observer(port);
  uart_disable_irq(port->irq);
  uart_destroy_endpoint(port);
  uart_free_port(port);
}

void uart_reset_baud(uart_port_t* port)
{
  uart_set_baud(port, 115200);
}
